export function sha256(text: string): string {
  const state = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c,
    0x1f83d9ab, 0x5be0cd19,
  ];
  const words = new Array<number>(64);
  const block = new Uint8Array(64);
  let used = 0, length = 0;
  const compress = () => {
    for (let index = 0; index < 16; index++) {
      const start = index * 4;
      words[index] = ((block[start] << 24) | (block[start + 1] << 16) | (block[start + 2] << 8) | block[start + 3]) >>> 0;
    }
    for (let index = 16; index < 64; index += 1) {
      const a = words[index - 15];
      const b = words[index - 2];
      const s0 = rotate(a, 7) ^ rotate(a, 18) ^ (a >>> 3);
      const s1 = rotate(b, 17) ^ rotate(b, 19) ^ (b >>> 10);
      words[index] = (words[index - 16] + s0 + words[index - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = state;
    for (let index = 0; index < 64; index += 1) {
      const s1 = rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25);
      const choice = (e & f) ^ (~e & g);
      const temp1 = (h + s1 + choice + SHA256_K[index] + words[index]) >>> 0;
      const s0 = rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (s0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }
    state[0] = (state[0] + a) >>> 0;
    state[1] = (state[1] + b) >>> 0;
    state[2] = (state[2] + c) >>> 0;
    state[3] = (state[3] + d) >>> 0;
    state[4] = (state[4] + e) >>> 0;
    state[5] = (state[5] + f) >>> 0;
    state[6] = (state[6] + g) >>> 0;
    state[7] = (state[7] + h) >>> 0;
  }
  const push = (byte: number) => { block[used++] = byte; if (used === 64) { compress(); used = 0; } };
  utf8(text, byte => { push(byte); length++; });
  push(0x80);
  while (used !== 56) push(0);
  const high = Math.floor(length * 8 / 0x100000000), low = length * 8 >>> 0;
  for (let shift = 24; shift >= 0; shift -= 8) push(high >>> shift & 255);
  for (let shift = 24; shift >= 0; shift -= 8) push(low >>> shift & 255);
  return state.map((value) => value.toString(16).padStart(8, "0")).join("");
}

export const isSha256 = (value: unknown): value is string =>
  typeof value === "string" && /^[0-9a-f]{64}$/.test(value);

export function utf8Length(text: string): number {
  let bytes = 0;
  for (const character of text) { const p = character.codePointAt(0)!; bytes += p <= 0x7f ? 1 : p <= 0x7ff ? 2 : p <= 0xffff ? 3 : 4; }
  return bytes;
}

function rotate(value: number, bits: number): number {
  return (value >>> bits) | (value << (32 - bits));
}

// @ref LLP 1018.008.007.002#6-reduce-the-remaining-preparation-and-publication-work — stream identical bytes without a generator result per byte.
/** Hashing needs no full byte-array allocation; the cursor collects its bounded payload. */
export function utf8(text: string, emit: (byte: number) => void): void {
  for (const character of text) {
    const p = character.codePointAt(0)!;
    if (p <= 0x7f) emit(p);
    else {
      if (p <= 0x7ff) emit(0xc0 | p >> 6);
      else {
        if (p <= 0xffff) emit(0xe0 | p >> 12);
        else { emit(0xf0 | p >> 18); emit(0x80 | p >> 12 & 63); }
        emit(0x80 | p >> 6 & 63);
      }
      emit(0x80 | p & 63);
    }
  }
}

const SHA256_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
  0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
  0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
  0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
  0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
  0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

/** Compare admitted scalar strings without allocating two codepoint arrays per index comparison. */
export function compareCodepoints(left: string, right: string): number {
  let a = 0, b = 0;
  while (a < left.length && b < right.length) {
    const x = left.codePointAt(a)!, y = right.codePointAt(b)!;
    if (x !== y) return x - y;
    a += x > 65535 ? 2 : 1; b += y > 65535 ? 2 : 1;
  }
  return left.length - a - (right.length - b);
}
